import { Body, Controller, Delete, Get, Injectable, Module, NotFoundException, Param, ParseIntPipe, Post } from "@nestjs/common"

type Book = { id: number; title: string; author: string }

@Injectable()
class BooksService {
    private books: Book[] = []
    private nextId = 1

    findAll(): Book[] {
        return this.books
    }

    findOne(id: number): Book {
        const book = this.books.find(b => b.id === id)
        if (!book) throw new NotFoundException(`Kitob #${id} topilmadi`)
        return book
    }

    create(data: Omit<Book, "id">): Book {
        const book = { id: this.nextId++, ...data }
        this.books.push(book)
        return book
    }

    remove(id: number): void {
        this.findOne(id)
        this.books = this.books.filter(b => b.id !== id)
    }
}

@Controller("books")
class BooksController {
    constructor(private readonly books: BooksService) {}

    @Get() findAll() { return this.books.findAll() }
    @Get(":id") findOne(@Param("id", ParseIntPipe) id: number) { return this.books.findOne(id) }
    @Post() create(@Body() body: Omit<Book, "id">) { return this.books.create(body) }
    @Delete(":id") remove(@Param("id", ParseIntPipe) id: number) { this.books.remove(id); return { deleted: id } }
}

@Module({ controllers: [BooksController], providers: [BooksService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/books", { title: "O'tkan kunlar", author: "A. Qodiriy" })
    await http.post("/books", { title: "Sariq devni minib", author: "X. To'xtaboyev" })
    await http.get("/books")
    await http.get("/books/2")
    await http.delete("/books/1")
    await http.get("/books/1")
    await http.close()
}
main()

