import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable()
class RatesService {
    private cache?: { value: number; until: number }
    calls = 0
    now = () => Date.now()
    private async fetchRate() { this.calls++; return 12650 }
    async usd() {
        if (this.cache && this.cache.until > this.now()) return this.cache.value
        const value = await this.fetchRate()
        this.cache = { value, until: this.now() + 60_000 }
        return value
    }
}
@Module({ providers: [RatesService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(RatesService)
    await s.usd(); await s.usd()
    const t = Date.now(); s.now = () => t + 61_000
    await s.usd()
    console.log("tashqi so'rovlar soni:", s.calls, "(2-chaqiruv keshdan, 3-si TTL tugagach)")
    await app.close()
}
main()

import { Injectable, Module } from "@nestjs/common"
