class DomainError extends Error { constructor(message: string, readonly code: string) { super(message) } }
class InsufficientFunds extends DomainError { constructor(need: number, has: number) { super(`${need} kerak, ${has} bor`, "INSUFFICIENT_FUNDS") } }
class AccountFrozen extends DomainError { constructor() { super("Hisob muzlatilgan", "ACCOUNT_FROZEN") } }

@Injectable()
class TransferService {
    transfer(balance: number, amount: number, frozen = false) {
        if (frozen) throw new AccountFrozen()
        if (amount > balance) throw new InsufficientFunds(amount, balance)
        return balance - amount
    }
}
@Module({ providers: [TransferService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(TransferService)
    for (const [b, a, f] of [[100, 30, false], [100, 300, false], [100, 10, true]] as const) {
        try { console.log("qoldiq:", s.transfer(b, a, f)) } catch (e) { const d = e as DomainError; console.log(d.code, "—", d.message) }
    }
    await app.close()
}
main()

