import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable()
class ProfileService {
    private inflight = new Map<number, Promise<{ id: number; name: string }>>()
    dbCalls = 0
    private async load(id: number) { this.dbCalls++; await new Promise(r => setTimeout(r, 20)); return { id, name: `user-${id}` } }
    get(id: number) {
        if (!this.inflight.has(id)) this.inflight.set(id, this.load(id).finally(() => this.inflight.delete(id)))
        return this.inflight.get(id)!
    }
}
@Module({ providers: [ProfileService] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(ProfileService)
    const results = await Promise.all([s.get(1), s.get(1), s.get(1), s.get(2)])
    console.log(results.map(r => r.name), "| DB'ga murojaat:", s.dbCalls)
    await app.close()
}
main()

