import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable()
class TodoService {
    private items: { id: number; text: string; done: boolean }[] = []
    add(text: string) { const t = { id: this.items.length + 1, text, done: false }; this.items.push(t); return t }
    toggle(id: number) { const t = this.items.find(i => i.id === id); if (t) t.done = !t.done; return t }
    pending() { return this.items.filter(i => !i.done).map(i => i.text) }
}

@Module({ providers: [TodoService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(TodoService)
    s.add("Kod yozish"); s.add("Test"); s.toggle(1)
    console.log(s.pending())
    await app.close()
}
main()

