import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Injectable()
class FibService {
    private memo = new Map<number, bigint>()
    computed = 0
    fib(n: number): bigint {
        if (n < 2) return BigInt(n)
        const hit = this.memo.get(n); if (hit !== undefined) return hit
        this.computed++
        const v = this.fib(n - 1) + this.fib(n - 2)
        this.memo.set(n, v)
        return v
    }
}

@Module({ providers: [FibService] }) class AppModule {}

