    providers: [
        Payme, Click, Stripe, CheckoutService,
        { provide: PAYMENT_PROVIDERS, useFactory: (...all: PaymentProvider[]) => all, inject: [Payme, Click, Stripe] },
    ],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const c = app.get(CheckoutService)
    console.log("UZS:", c.options("UZS"))
    console.log("USD:", c.options("USD"))
    await app.close()
}
main()

