import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

interface Validator { name: string; check(text: string): boolean }
const VALIDATORS = "VALIDATORS"

@Injectable() class NotEmpty implements Validator { name = "bo'sh emas"; check(t: string) { return t.trim().length > 0 } }
@Injectable() class NoLinks implements Validator { name = "havolasiz"; check(t: string) { return !/https?:\/\//.test(t) } }
@Injectable() class MaxLen implements Validator { name = "200 belgidan qisqa"; check(t: string) { return t.length <= 200 } }

@Injectable()
class CommentService {
    constructor(@Inject(VALIDATORS) private readonly validators: Validator[]) {}
    validate(text: string) { return this.validators.filter(v => !v.check(text)).map(v => v.name) }
}

@Module({
    providers: [
        NotEmpty, NoLinks, MaxLen,
        { provide: VALIDATORS, useFactory: (...vs: Validator[]) => vs, inject: [NotEmpty, NoLinks, MaxLen] },
        CommentService,
    ],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const s = app.get(CommentService)
    console.log("'Zo'r maqola' xatolari:", s.validate("Zo'r maqola"))
    console.log("'Mana: https://spam.test' xatolari:", s.validate("Mana: https://spam.test"))
    await app.close()
}
main()

