import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { EventEmitter } from "node:events"

// Tashqi kutubxonadan kelgan tayyor obyekt
const bus = new EventEmitter()
const BUS = "BUS"

@Injectable() class Publisher { constructor(@Inject(BUS) private readonly bus: EventEmitter) {} publish(e: string) { this.bus.emit("event", e) } }
@Injectable() class Subscriber { received: string[] = []; constructor(@Inject(BUS) bus: EventEmitter) { bus.on("event", (e: string) => this.received.push(e)) } }

@Module({ providers: [{ provide: BUS, useValue: bus }, Publisher, Subscriber] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    app.get(Publisher).publish("user.created"); app.get(Publisher).publish("order.paid")
    console.log(app.get(Subscriber).received)
    await app.close()
}
main()

