import { Controller, Get, Injectable, Module, Scope } from "@nestjs/common"
import { ContextId, ContextIdFactory, ContextIdStrategy, HostComponentInfo } from "@nestjs/core"

const tenants = new Map<string, ContextId>()

class TenantContextStrategy implements ContextIdStrategy {
    attach(contextId: ContextId, request: any) {
        const tenant = request.headers["x-tenant"] ?? "default"
        let tenantSubTree = tenants.get(tenant)
        if (!tenantSubTree) { tenantSubTree = ContextIdFactory.create(); tenants.set(tenant, tenantSubTree) }
        return (info: HostComponentInfo) => (info.isTreeDurable ? tenantSubTree! : contextId)
    }
}

