import { Controller, Get, Inject, Injectable, Module, Scope } from "@nestjs/common"
import { ContextId, ContextIdFactory, ContextIdStrategy, HostComponentInfo, REQUEST } from "@nestjs/core"
import type { Request } from "express"

const tenants = new Map<string, ContextId>()

class TenantContextIdStrategy implements ContextIdStrategy {
    attach(contextId: ContextId, request: Request) {
        const tenant = String(request.headers["x-tenant"] ?? "default")
        let tenantSubTree = tenants.get(tenant)
        if (!tenantSubTree) { tenantSubTree = ContextIdFactory.create(); tenants.set(tenant, tenantSubTree) }
        return {
            resolve: (info: HostComponentInfo) => (info.isTreeDurable ? tenantSubTree! : contextId),
            payload: { tenant },
        }
    }
}

