import { Controller, Get, Inject, Injectable, Module, Scope } from "@nestjs/common"
import { ContextId, ContextIdFactory, ContextIdStrategy, HostComponentInfo, REQUEST } from "@nestjs/core"
import type { Request } from "express"

const tenants = new Map<string, ContextId>()
class TenantStrategy implements ContextIdStrategy {
    attach(contextId: ContextId, req: Request) {
        const t = (req.headers["x-tenant"] as string) ?? "default"
        let tenantId = tenants.get(t)
        if (!tenantId) { tenantId = ContextIdFactory.create(); tenants.set(t, tenantId) }
        return (info: HostComponentInfo) => (info.isTreeDurable ? tenantId! : contextId)
    }
}

