import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

let attempts = 0
async function flakyConnect() {
    attempts++
    if (attempts < 3) throw new Error(`urinish ${attempts}: ulanish rad etildi`)
    return { connectedOn: attempts }
}

async function retry<T>(fn: () => Promise<T>, times: number, delayMs: number): Promise<T> {
    for (let i = 1; ; i++) {
        try { return await fn() } catch (e) {
            console.log((e as Error).message)
            if (i >= times) throw e
            await new Promise(r => setTimeout(r, delayMs))
        }
    }
}

@Injectable() class Repo { constructor(@Inject("DB") readonly db: { connectedOn: number }) {} }

@Module({ providers: [{ provide: "DB", useFactory: () => retry(flakyConnect, 5, 10) }, Repo] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log("ulandi, urinish:", app.get(Repo).db.connectedOn)
    await app.close()
}
main()

