@Module({ providers: [{ provide: "JWT", useFactory: async () => { const s = process.env.JWT_SECRET; if (!s) throw new Error("JWT_SECRET o'rnatilmagan"); return s } }] })
class AppModule {}

async function main() {
    try { await NestFactory.createApplicationContext(AppModule, { logger: false, abortOnError: false }) }
    catch (e) { console.log((e as Error).message) }
}
main()

import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

@Module({
    providers: [
        { provide: "S1", useFactory: async () => 2 },
