    await app.close()
}
main()

import { Inject, Injectable, InjectionToken, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

type Flags = { beta: boolean }
const FLAGS: InjectionToken<Flags> = "FLAGS"
@Injectable() class Ui { constructor(@Inject(FLAGS) private f: Flags) {} header() { return this.f.beta ? "Yangi dizayn (beta)" : "Klassik" } }

@Module({ providers: [Ui, { provide: FLAGS, useFactory: async (): Promise<Flags> => ({ beta: true }) }] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log(app.get(Ui).header())
    await app.close()
}
main()

import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

const load = <T extends object>(v: T, ms: number) => new Promise<T>(r => setTimeout(() => r(v), ms))
@Module({ providers: [{ provide: "BOOT", useFactory: async () => { const [a, b] = await Promise.all([load({ users: 10 }, 10), load({ orders: 4 }, 5)]); return { ...a, ...b } } }] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log(app.get("BOOT"))
    await app.close()
}
main()

import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

let loaded = 0
@Injectable() class Reports {
    constructor(@Inject("LOAD_BIG") private loadBig: () => Promise<number[]>) {}
    async summary(need: boolean) { return need ? (await this.loadBig()).length : "kerak emas" }
}
@Module({ providers: [Reports, { provide: "LOAD_BIG", useFactory: async () => async () => { loaded++; return [1, 2, 3] } }] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const r = app.get(Reports)
    console.log(await r.summary(false), "| yuklangan:", loaded)
    console.log(await r.summary(true), "| yuklangan:", loaded)
    await app.close()
}
main()

