import { Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

const timed = (name: string, ms: number) => ({ provide: name, useFactory: async () => { const t = Date.now(); await new Promise(r => setTimeout(r, ms)); return Date.now() - t >= ms - 2 } })
@Module({ providers: [timed("DB", 20), timed("CACHE", 10)] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log("DB kutildi:", app.get("DB"), "| CACHE kutildi:", app.get("CACHE"))
    await app.close()
}
main()

import { Inject, Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"

const wait = (ms: number) => new Promise(r => setTimeout(r, ms))
@Injectable() class Migrations {
    constructor(@Inject("POOL") private pool: { size: number }, @Inject("SCHEMA") private schema: string[]) {}
    info() { return `pool=${this.pool.size}, jadvallar: ${this.schema.join(", ")}` }
}
@Module({
    providers: [
        Migrations,
        { provide: "POOL", useFactory: async () => { await wait(5); return { size: 10 } } },
        { provide: "SCHEMA", useFactory: async (pool: { size: number }) => { await wait(5); return pool.size > 0 ? ["users", "orders"] : [] }, inject: ["POOL"] },
    ],
})
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    console.log(app.get(Migrations).info())
    await app.close()
}
main()
